export function getApiV2QueryOptions<
  TData = Awaited<ReturnType<typeof parseResponse<Awaited<ReturnType<typeof client.api.v2.$get>>>>>,
  TError = DefaultError,
>(options?: ClientRequestOptions) {
  return queryOptions<
    Awaited<ReturnType<typeof parseResponse<Awaited<ReturnType<typeof client.api.v2.$get>>>>>,
    TError,
    TData,
    ReturnType<typeof getApiV2QueryKey>
  >({
    queryKey: getApiV2QueryKey(),
    queryFn({ signal }) {
      return parseResponse(
        client.api.v2.$get(undefined, { ...options, init: { ...options?.init, signal } }),
      )
    },
  })
}

